begin;

revoke all on function public.handle_new_user() from public, anon, authenticated;
revoke all on function public.is_admin() from public, anon;
revoke all on function public.submit_menu_review(text, smallint, text) from public, anon, authenticated;
revoke all on function public.list_published_reviews(text) from public, anon, authenticated;

alter table public.menu_reviews
  add column author_name text;

update public.menu_reviews
set author_name = coalesce(
  (select nullif(display_name, '') from public.profiles where id = menu_reviews.user_id),
  'Cheeseful customer'
)
where author_name is null;

alter table public.menu_reviews
  alter column author_name set default 'Cheeseful customer',
  alter column author_name set not null;

create or replace function public.set_review_author()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  select coalesce(nullif(display_name, ''), 'Cheeseful customer')
  into new.author_name
  from public.profiles
  where id = auth.uid();

  new.author_name := coalesce(new.author_name, 'Cheeseful customer');
  return new;
end;
$$;

create trigger menu_reviews_set_author_name
before insert or update of user_id on public.menu_reviews
for each row execute procedure public.set_review_author();

revoke all on function public.set_review_author() from public, anon, authenticated;

create or replace function public.is_admin()
returns boolean
language sql
stable
set search_path = public
as $$
  select exists (
    select 1
    from public.profiles
    where id = auth.uid()
      and role = 'admin'
  );
$$;

grant execute on function public.is_admin() to authenticated;

drop function public.submit_menu_review(text, smallint, text);
drop function public.list_published_reviews(text);

drop policy "Profiles are visible to their owner or an admin" on public.profiles;
drop policy "Public can read available menu items" on public.restaurant_menu_items;
drop policy "Published reviews are public and users can see their own" on public.menu_reviews;

create policy "Profiles are visible to their owner"
on public.profiles
for select
to authenticated
using (id = auth.uid());

create policy "Anonymous visitors can read available menu items"
on public.restaurant_menu_items
for select
to anon
using (available);

create policy "Signed-in users can read available menu items or manage as admin"
on public.restaurant_menu_items
for select
to authenticated
using (available or public.is_admin());

create policy "Anonymous visitors can read published reviews"
on public.menu_reviews
for select
to anon
using (status = 'published');

create policy "Signed-in users can read published reviews, their own reviews, or moderate as admin"
on public.menu_reviews
for select
to authenticated
using (status = 'published' or user_id = auth.uid() or public.is_admin());

create policy "Customers can update their own reviews for re-moderation"
on public.menu_reviews
for update
to authenticated
using (user_id = auth.uid())
with check (user_id = auth.uid() and status = 'pending');

commit;
